// 일반적인 컴파일에서는 이 심볼이 정의되지 않은 weak symbol로 남는다.
#include <stdio.h>

int main(void)
{
    printf("hello\n");
    return 0;
}

#include <stdio.h>
#include <errno.h>
#include <string.h>

int main(void)
{
    FILE *fp = fopen("/no/such/file", "r");
    if (!fp) {
        // errno는 매크로: *__errno_location()
        printf("errno = %d (%s)\n", errno, strerror(errno));
    }
    return 0;
}

#include <stdio.h>

int main(void)
{
    printf("value = %d\n", 42); // -D_FORTIFY_SOURCE=2 -O2 로 컴파일하면 __printf_chk(1, ...)로 치환됨
    return 0;
}

#include <string.h>

int main(void)
{
    char buf[16];
    char src[64] = "0123456789ABCDEF0123456789ABCDEF";
    memcpy(buf, src, sizeof(src)); // buf 크기가 컴파일 타임에 16으로 알려져 __memcpy_chk로 치환됨
    return 0;
}

#include <string.h>

int main(void)
{
    char buf[8];
    const char *src = "this string is way longer than 8 bytes";
    strcpy(buf, src); // buf 크기가 컴파일 타임에 8로 알려져 __strcpy_chk로 치환됨
    return 0;
}

#include <stdio.h>

int main(void)
{
    char buf[8];
    int id = 123456789;
    sprintf(buf, "id=%d", id); // buf 크기가 컴파일 타임에 8로 알려져 __sprintf_chk로 치환됨, 결과 길이 초과 시 abort
    return 0;
}

